    parameters = SchemaField(name="parameters", nested_klass=Parameters, not_null=True)
    modification_property = SchemaField(name="modificationProperty", klass=PlanOperations, not_null=True)
    instance_id_parameter = SchemaField(name="instanceIdParameter", not_null=True)
    max_occurs = SchemaField(name="maxOccurs", optional=True)
    min_occurs = SchemaField(name="minOccurs", optional=True)
